#include <cg3/geometry/point2.h>
#include <cg3/geometry/segment2.h>
#include <cg3/cgal/segment_intersections2.h>
#include <CGAL/Simple_cartesian.h>
#include <CGAL/intersections.h>

typedef CGAL::Simple_cartesian<double> CK;
typedef CK::Point_2 CK_Point_2;
typedef CK::Segment_2 CK_Segment_2;

std::vector<cg3::Point2d> segmentIntersections(const std::vector<cg3::Segment2d>& segments) {
    std::set<cg3::Point2d> intersections;

    for (size_t i = 0; i < segments.size(); ++i) {
        for (size_t j = i + 1; j < segments.size(); ++j) {
            const cg3::Segment2d& seg1 = segments[i];
            const cg3::Segment2d& seg2 = segments[j];

            CK_Segment_2 cgalSeg1(CK_Point_2(seg1.p1().x(), seg1.p1().y()), CK_Point_2(seg1.p2().x(), seg1.p2().y()));
            CK_Segment_2 cgalSeg2(CK_Point_2(seg2.p1().x(), seg2.p1().y()), CK_Point_2(seg2.p2().x(), seg2.p2().y()));

            auto result = CGAL::intersection(cgalSeg1, cgalSeg2);
            if (result) {
                if (const CK_Point_2* point = boost::get<CK_Point_2>(&*result)) {
                    intersections.insert(cg3::Point2d(point->x(), point->y()));
                }
                // Ignore segment intersections (only care about points)
            }
        }
    }

    return std::vector<cg3::Point2d>(intersections.begin(), intersections.end());
}

